{
  "name": "agyforclaude",
  "version": "0.0.3",
  "description": "Universal MCP server + Skill for delegating tasks to the Antigravity (Gemini) CLI",
  "main": "dist/cli.js",
  "type": "module",
  "bin": {
    "agyforclaude": "./bin/agyforclaude"
  },
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "prepublishOnly": "npm run build",
    "postinstall": "node dist/cli.js setup",
    "preuninstall": "node dist/cli.js uninstall",
    "test": "npm run build && node --test dist/test/integration.test.js"
  },
  "keywords": [
    "antigravity",
    "gemini",
    "mcp",
    "claude",
    "opencode",
    "ai-delegation"
  ],
  "author": "YOUR NAME <you@example.com>",
  "license": "MIT",
  "engines": {
    "node": ">=18.0.0"
  },
  "types": "dist/cli.d.ts",
  "repository": {
    "type": "git",
    "url": "https://github.com/theoreticalthread/agyforclaude.git"
  },
  "bugs": {
    "url": "https://github.com/theoreticalthread/agyforclaude/issues"
  },
  "homepage": "https://github.com/theoreticalthread/agyforclaude#readme",
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.6.0"
  },
  "devDependencies": {
    "@types/node": "^20.0.0",
    "typescript": "^5.0.0"
  },
  "files": [
    "dist/",
    "templates/",
    "bin/",
    "README.md",
    "LICENSE"
  ]
}
